void quicksort(double* a, std::size_t n) {
    while (n > 1) {
        const double pivot = a[n / 2];
        std::size_t lo = 0, i = 0, hi = n;
        while (i < hi) {
            if (a[i] < pivot) {
                std::swap(a[lo++], a[i++]);
            } else if (a[i] > pivot) {
                std::swap(a[i], a[--hi]);
            } else {
                ++i;
            }
